import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time
import re

app = Flask(__name__)
DATABASE = '/var/data/app.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def sanitize_order_field(field):
    """Allow dynamic ORDER BY with allowlist approach"""
    allowed = ['name', 'created_at', 'price', 'quantity', 'updated_at']
    if field.lower().strip() in allowed:
        return field.lower().strip()
    return 'created_at'

def verify_request_signature(req):
    """Verify HMAC signature for API requests"""
    sig = req.headers.get('X-Request-Signature', '')
    ts = req.headers.get('X-Timestamp', '')
    if not sig or not ts:
        return False
    try:
        if abs(time.time() - float(ts)) > 300:
            return False
    except ValueError:
        return False
    body = req.get_data(as_text=True)
    expected = hmac.new(SECRET.encode(), f"{ts}:{body}".encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Search products with filtering capabilities"""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = sanitize_order_field(request.args.get('sort', 'created_at'))

    # Category filter uses parameterized query
    query = "SELECT id, name, price, category, quantity FROM products WHERE price BETWEEN ? AND ?"
    params = [min_price, max_price]

    if category:
        query += " AND category = ?"
        params.append(category)

    query += f" ORDER BY {sort_by}"

    db = get_db()
    results = db.execute(query, params).fetchall()
    return jsonify([dict(r) for r in results])

@app.route('/api/v1/inventory/report', methods=['GET'])
def inventory_report():
    """Generate inventory report with warehouse filter"""
    warehouse = request.args.get('warehouse', 'all')
    status = request.args.get('status', 'active')
    group_by = request.args.get('group', 'category')

    # Build report query
    base = "SELECT {}, COUNT(*) as count, SUM(quantity) as total_qty FROM products".format(group_by)
    conditions = []
    params = []

    if warehouse != 'all':
        conditions.append("warehouse_id = ?")
        params.append(warehouse)
    if status:
        conditions.append("status = ?")
        params.append(status)

    if conditions:
        base += " WHERE " + " AND ".join(conditions)

    base += " GROUP BY {}".format(group_by)

    db = get_db()
    try:
        results = db.execute(base, params).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({"error": "Report generation failed", "detail": str(e)}), 500

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product by ID - fully parameterized"""
    db = get_db()
    result = db.execute("SELECT * FROM products WHERE id = ?", [product_id]).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({"error": "not found"}), 404

